package dev.eugheist.tc4modern;

import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.fluids.*;
import net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;

@EventBusSubscriber(modid=TC4Modern.MODID,value=Dist.CLIENT)
public final class GolemLiquidAudit {
 static final BlockPos BASE=new BlockPos(280,121,-90),SOURCE=BASE.offset(6,0,0),POOL=BASE.offset(8,0,3),ISOLATED=BASE.offset(12,0,6);static StrawGolem golem;static SpaEntity home,source;static int ticks;static volatile boolean done;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_LIQUID FAIL "+s);System.out.println("TC4_LIQUID PASS "+s);}
 static void mark(BlockPos p,Direction face){var t=new CompoundTag();t.putLong("pos",p.asLong());t.putByte("side",(byte)face.get3DDataValue());golem.markers.add(t);}
 static void setup(ServerPlayer p){var l=p.serverLevel();p.removeAllEffects();p.setHealth(p.getMaxHealth());p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getInventory().clearContent();p.connection.teleport(BASE.getX()+3,BASE.getY()+4,BASE.getZ()-7,20,25);p.getAbilities().flying=true;p.onUpdateAbilities();l.setDayTime(6000);l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,l.getServer());l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_WATER_SOURCE_CONVERSION).set(false,l.getServer());l.getEntitiesOfClass(Entity.class,new AABB(BASE).inflate(30)).stream().filter(e->!(e instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);for(int x=-5;x<18;x++)for(int z=-8;z<10;z++)for(int y=-1;y<6;y++)l.setBlock(BASE.offset(x,y,z),(y==-1?Blocks.STONE:Blocks.AIR).defaultBlockState(),3);l.getEntitiesOfClass(ItemEntity.class,new AABB(BASE).inflate(30)).forEach(Entity::discard);
  for(var pos:java.util.List.of(BASE,SOURCE)){l.setBlock(pos,Hygiene.SPA.get().defaultBlockState(),3);l.setBlock(pos.below(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);}home=(SpaEntity)l.getBlockEntity(BASE);source=(SpaEntity)l.getBlockEntity(SOURCE);home.tank.setFluid(FluidStack.EMPTY);source.tank.setFluid(new FluidStack(Fluids.WATER,4000));golem=GolemHarvestAudit.golem(p,GolemMaterial.THAUMIUM,BASE.east(),5);golem.homeFace=Direction.EAST;golem.owner=p.getUUID();golem.filters.setItem(0,new ItemStack(Items.LAVA_BUCKET));mark(SOURCE,Direction.WEST);
  check(golem.filterCount()==1&&golem.fluidCarryLimit()==5000,"original single fluid filter and thaumium 5000mB capacity");var copy=new StrawGolem(Golemancy.ENTITY.get(),l);copy.material(GolemMaterial.THAUMIUM,true);copy.installUpgrade(1);check(copy.fluidCarryLimit()==6000,"Earth upgrade increases fluid capacity by sqrt carry formula");var task=new GolemLiquidGoal(golem);check(task.candidate(SOURCE,Direction.UP,home.tank)==null,"blocked top fluid capability respected");check(!task.accepts(new FluidStack(Fluids.WATER,1000)),"filled lava bucket rejects water");var recipe=CrucibleRecipes.byKey().get("CoreLiquid");check(recipe!=null&&recipe.aspects.visSize()==10&&recipe.key.equals("CORELIQUID"),"original liquid crucible recipe");
  p.getInventory().setItem(0,new ItemStack(Golemancy.LIQUID.get()));p.getInventory().setItem(1,new ItemStack(Golemancy.LUMBER.get()));p.containerMenu.broadcastChanges();for(int i=0;i<2;i++){var drop=new ItemEntity(l,BASE.getX()+i*.6+.5,BASE.getY()+2,BASE.getZ()-2,new ItemStack(i==0?Golemancy.LIQUID.get():Golemancy.LUMBER.get()));drop.setDeltaMovement(Vec3.ZERO);drop.setNoGravity(true);drop.setNeverPickUp();l.addFreshEntity(drop);}
 }
 static void beginPool(){check(home.tank.getFluidAmount()==4000&&source.tank.isEmpty()&&golem.fluidCarried.isEmpty(),"natural sided tank transfer conserves all 4000mB");home.tank.drain(Integer.MAX_VALUE,FluidAction.EXECUTE);golem.markers.clear();var l=golem.level();for(int x=-1;x<=3;x++)for(int z=-1;z<=1;z++)l.setBlock(POOL.offset(x,0,z),(x>=0&&x<=2&&z==0?Blocks.WATER:Blocks.STONE).defaultBlockState(),3);l.setBlock(ISOLATED,Blocks.WATER.defaultBlockState(),3);for(var side:Direction.Plane.HORIZONTAL)l.setBlock(ISOLATED.relative(side),Blocks.STONE.defaultBlockState(),3);mark(POOL,Direction.UP);golem.installUpgrade(3);golem.installUpgrade(5);golem.filters.setItem(0,new ItemStack(Items.LAVA_BUCKET));golem.filters.setItem(1,new ItemStack(Items.WATER_BUCKET));check(golem.filterCount()==2&&new GolemLiquidGoal(golem).accepts(new FluidStack(Fluids.WATER,1000)),"Fire second fluid filter participates");var candidate=new GolemLiquidGoal.Source(POOL,Direction.UP,new FluidStack(Fluids.WATER,1000),false);check(new GolemLiquidGoal(golem).pump(candidate).equals(POOL.east(2)),"Entropy selects furthest connected source first");}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.golemLiquidAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null)return;ticks++;if(ticks==10&&mc.player.isDeadOrDying())mc.player.respawn();var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==40)server.execute(()->setup(server.getPlayerList().getPlayer(id)));if(ticks==140){for(var item:java.util.List.of(Golemancy.LIQUID.get(),Golemancy.LUMBER.get())){var model=mc.getItemRenderer().getModel(new ItemStack(item),mc.level,mc.player,0);check(!model.isGui3d(),"flat icon "+item);for(var context:java.util.List.of(ItemDisplayContext.GUI,ItemDisplayContext.GROUND,ItemDisplayContext.FIRST_PERSON_RIGHT_HAND,ItemDisplayContext.THIRD_PERSON_RIGHT_HAND)){var scale=model.getTransforms().getTransform(context).scale;check(scale.x<=1&&scale.y<=1&&scale.z<=1,"bounded model scale "+item+" "+context);}}LiquidDeathAudit.shot(mc,"golem-liquid-hand-and-drops.png");}if(ticks==150)server.execute(()->{check(source.tank.getFluidAmount()==4000&&home.tank.isEmpty(),"wrong fluid filter never drains source");golem.filters.setItem(0,new ItemStack(Items.WATER_BUCKET));});if(ticks==500)server.execute(GolemLiquidAudit::beginPool);if(ticks==850)server.execute(()->{check(home.tank.getFluidAmount()==3000&&golem.fluidCarried.isEmpty(),"Entropy drains connected three-source pool into home");for(int i=0;i<3;i++)check(!golem.level().getFluidState(POOL.east(i)).isSource(),"source consumed "+i);check(golem.level().getFluidState(ISOLATED).isSource(),"disconnected source untouched");golem.markers.clear();home.tank.setFluid(new FluidStack(Fluids.WATER,4800));golem.fluidCarried(new FluidStack(Fluids.WATER,700));});if(ticks==950)server.execute(()->{check(home.tank.getFluidAmount()==5000&&golem.fluidCarried.getAmount()==500,"partial home fill keeps exact remaining 500mB");var tag=new CompoundTag();golem.addAdditionalSaveData(tag);var restored=new StrawGolem(Golemancy.ENTITY.get(),golem.level());restored.readAdditionalSaveData(tag);check(restored.core()==5&&restored.fluidCarried.getAmount()==500&&restored.fluidCarried.is(Fluids.WATER),"fluid payload survives entity save");restored.restoreItem(golem.asItem());check(restored.fluidCarried.getAmount()==500,"fluid payload survives bell item roundtrip");var p=server.getPlayerList().getPlayer(id);p.connection.teleport(golem.getX()+1,golem.getY(),golem.getZ()-1,0,0);p.openMenu(golem,b->b.writeVarInt(golem.getId()));});if(ticks==990){check(mc.screen instanceof GolemClient.Screen&&((GolemMenu)mc.player.containerMenu).filterCount==2,"liquid client GUI synchronizes two filters");check(mc.player.containerMenu.getSlot(0).isActive()&&mc.player.containerMenu.getSlot(1).isActive()&&!mc.player.containerMenu.getSlot(2).isActive(),"inactive extra filter slots hidden");LiquidDeathAudit.shot(mc,"golem-liquid-filters.png");mc.player.closeContainer();}if(ticks==1020)server.execute(()->{var p=server.getPlayerList().getPlayer(id);var bell=new ItemStack(Golemancy.BELL.get());((Golemancy.Bell)bell.getItem()).onLeftClickEntity(bell,p,golem);var nearby=p.level().getEntitiesOfClass(ItemEntity.class,new AABB(golem.blockPosition()).inflate(4));check(nearby.stream().noneMatch(e->e.getItem().is(Items.WATER_BUCKET)),"visual bucket never becomes free dropped item");check(nearby.stream().anyMatch(e->e.getItem().is(Golemancy.placer(GolemMaterial.THAUMIUM).get())&&FluidStack.parseOptional(p.registryAccess(),NoteData.tag(e.getItem()).getCompound("FluidCarried")).getAmount()==500),"real bell retrieval preserves carried fluid");done=true;});if(ticks==1040){check(done,"all server liquid checks completed");System.out.println("TC4_LIQUID ALL PASS");mc.stop();}}
}
